"""Step 2: the loop as a circuit, generated by PySpice and solved by ngspice."""
from pathlib import Path

import pytest

from _tools import needs_ngspice
from mct import circuit, compare, design, spice
from mct.params import STEP, T_END

NETLISTS = Path(__file__).resolve().parent.parent / "netlists"


@pytest.mark.parametrize("mode", circuit.MODES)
def test_committed_netlists_are_what_the_generator_writes(mode):
    committed = (NETLISTS / f"{mode}.cir").read_text(encoding="ascii")
    assert committed == circuit.batch_deck(mode, out=f"{mode}.txt")


def test_component_values_realise_the_pi():
    v = circuit.component_values()
    assert v["Ci"] == pytest.approx(2.5e-6)  # Ri*Ci = 1/ki = 25 ms
    assert v["Rp2"] / v["Rp1"] == pytest.approx(20)  # kp


def test_mechanical_analog_elements():
    text = circuit.netlist("linear")
    for line in ("Ftorque 0 w Vsense 0.01", "CJ w 0 0.01", "Rb w 0 10.0",
                 "Eemf a3 0 w 0 0.01", "La a1 a2 0.5"):
        assert line in text.splitlines()


def _check_against_python_control(t_src, w_src, pc_linear):
    t, y = pc_linear
    w = compare.on_grid(t_src, w_src, t)
    a = compare.agreement(t, y, w, STEP)
    assert a["max_err_pct"] < 1.0
    return a


@needs_ngspice
def test_pyspice_linear_loop_matches_python_control(pc_linear):
    t, w, va = spice.run_pyspice("linear")
    assert t[-1] == pytest.approx(T_END)
    a = _check_against_python_control(t, w, pc_linear)
    assert a["max_err_pct"] < 0.1  # measured: see results/step2_spice.txt
    m = design.metrics(pc_linear[0], compare.on_grid(t, w, pc_linear[0]), STEP)
    assert m["overshoot_pct"] == pytest.approx(1.71, abs=0.05)


@needs_ngspice
def test_ngspice_batch_gives_the_same_answer_as_pyspice(pc_linear):
    t1, w1, _ = spice.run_pyspice("linear")
    t2, w2, _ = spice.run_batch("linear")
    t = pc_linear[0]
    a = compare.agreement(t, compare.on_grid(t1, w1, t), compare.on_grid(t2, w2, t), STEP)
    assert a["max_err_pct"] < 0.01
    _check_against_python_control(t2, w2, pc_linear)


@needs_ngspice
@pytest.mark.parametrize("gain", [1e4, 1e6])
def test_finite_opamp_gain_leaves_a_steady_error_of_v_over_a(gain, pc_linear):
    """The integrator op-amp's DC gain is its open-loop gain A, not infinity, so the loop
    settles where A*e equals the 10.01 V the motor needs: e = 10.01/A rad/s.
    Measured against python-control at 3 s, which still carries a 3e-6 rad/s tail
    of the slow closed-loop pole."""
    t, w, _ = spice.run_pyspice("linear", opamp_gain=gain)
    final_err = pc_linear[1][-1] - w[-1]
    assert final_err == pytest.approx(10.01 / gain, rel=0.1)
